#!/bin/bash
# tools/prune-release.sh [--apply] -- remove stale, duplicate and generated files from the tree.
#
# Dry run by default: prints each action with the reason. --apply performs it. Idempotent: paths that no longer
# exist are skipped silently. A tracked path inside a git work tree is removed with `git rm -r -q` (the removal is
# then staged, ready to commit); anything else with `rm -rf`. Same shape as v32sim's tools/prune-release.sh.
set -euo pipefail

APPLY=0
case "${1:-}" in
    "") ;;
    --apply) APPLY=1 ;;
    -h|--help) sed -n '2,6p' "$0"; exit 0 ;;
    *) echo "usage: $0 [--apply]" >&2; exit 2 ;;
esac

cd "$(dirname "${BASH_SOURCE[0]}")/.."

INGIT=0
if command -v git >/dev/null 2>&1 && git rev-parse --is-inside-work-tree >/dev/null 2>&1; then INGIT=1; fi

N=0
prune() {   # prune PATH REASON
    local p=$1 why=$2
    [ -e "$p" ] || [ -L "$p" ] || return 0
    N=$((N + 1))
    local how="rm -rf"
    if [ $INGIT = 1 ] && [ -n "$(git ls-files -- "$p" 2>/dev/null | head -n 1)" ]; then how="git rm -r -q"; fi
    if [ $APPLY = 1 ]; then
        printf 'remove  %-52s %s\n' "$p" "($why)"
        if [ "$how" = "git rm -r -q" ]; then
            git rm -r -q -- "$p"
            rm -rf -- "$p"          # whatever untracked part of a directory git left behind
        else
            rm -rf -- "$p"
        fi
    else
        printf 'would %-13s %-44s %s\n' "$how" "$p" "($why)"
    fi
}

# ---------------------------------------------------------------------------------------------------------------------
# 1. Material older tooling cloned into the tree
# ---------------------------------------------------------------------------------------------------------------------
prune tools/vircon32/ComputerSoftware \
    "old build-tools.sh clone; ComputerSoftware is found beside the project now (../ComputerSoftware[.git])"

# ---------------------------------------------------------------------------------------------------------------------
# 2. Private copies of v32sim's tools (v32sim is the one place for running, profiling and debugging)
# ---------------------------------------------------------------------------------------------------------------------
for f in v32run.cpp v32prof.cpp v32shot.cpp v32peek.cpp; do
    prune "tools/vircon32/$f" "superseded by v32sim's tools/oracle/ ($f is built there as ${f%.cpp})"
done
prune tools/vircon32/shim            "duplicate of v32sim's tools/oracle/shim/SDL.h"
prune tools/vircon32/v32io-script.py "duplicate of v32sim's tools/v32io-script.py"

# ---------------------------------------------------------------------------------------------------------------------
# 3. Generated files that should never be committed
# ---------------------------------------------------------------------------------------------------------------------
prune tests/Make.sh  "build script a test run used to write beside tests/98sample.cpp"
prune tests/Make.bat "build script a test run used to write beside tests/98sample.cpp"
prune src/parser.output     "bison -v report"
prune counterexamples.txt   "bison -Wcounterexamples report"

# Build outputs: removed only when git tracks them (an untracked build tree is `make clean`'s business).
if [ $INGIT = 1 ]; then
    for d in out obj bin tools/vircon32/bin; do
        while IFS= read -r f; do
            [ -n "$f" ] && prune "$f" "build output tracked by git ($d/ is regenerated by make)"
        done < <(git ls-files -- "$d" 2>/dev/null)
    done
fi

# Editor, merge and OS leftovers anywhere in the tree (build and output trees excluded).
while IFS= read -r -d '' f; do
    prune "${f#./}" "editor/merge/OS leftover"
done < <(find . \( -path ./.git -o -path ./out -o -path ./obj -o -path ./tools/vircon32/bin \) -prune -o \
             -type f \( -name '*~' -o -name '*.orig' -o -name '*.rej' -o -name '*.bak' -o -name '*.swp' \
                        -o -name '.DS_Store' -o -name 'core' \) -print0)

if [ $N = 0 ]; then
    echo "nothing to prune"
elif [ $APPLY = 0 ]; then
    echo "$N path(s); run with --apply to remove them"
elif [ $INGIT = 1 ]; then
    echo "$N path(s) removed; tracked removals are staged (git status)"
else
    echo "$N path(s) removed"
fi
